with agg_measures_position as (select "lhu", "position_ref", (2 - bit_count(grouping("lhu", "position_ref"))) as sub_depth, sum("daily_trading_pnl") as "daily_trading_pnl" from risk_snapshot_position_live base where true group by grouping sets ((), ("lhu"), ("lhu", "position_ref"))),
agg_measures_instrument as (select "lhu", "position_ref", (2 - bit_count(grouping("lhu", "position_ref"))) as sub_depth, sum("npv") as "npv" from risk_snapshot_instrument_live base where true group by grouping sets ((), ("lhu"), ("lhu", "position_ref"))),
agg_measures_underlying as (select "lhu", "underlying_ref", "position_ref", (3 - bit_count(grouping("lhu", "underlying_ref", "position_ref"))) as sub_depth, sum("delta01") as "delta01", sum("gamma01") as "gamma01", sum("vega01") as "vega01" from risk_snapshot_underlying_live base where true group by grouping sets ((), ("lhu"), ("lhu", "underlying_ref"), ("lhu", "underlying_ref", "position_ref"))),
agg_measures_underlying_pair as (select "lhu", "position_ref", (2 - bit_count(grouping("lhu", "position_ref"))) as sub_depth, sum("cross_gamma02") as "cross_gamma02" from risk_snapshot_underlying_pair_live base where true group by grouping sets ((), ("lhu"), ("lhu", "position_ref"))),
spine as (select distinct * from (select NULL as "lhu", NULL as "underlying_ref", NULL as "position_ref", 0 as row_depth union all select agg_measures_position."lhu", NULL, agg_measures_position."position_ref", agg_measures_position.sub_depth from agg_measures_position where agg_measures_position.sub_depth in (1) union all select agg_measures_instrument."lhu", NULL, agg_measures_instrument."position_ref", agg_measures_instrument.sub_depth from agg_measures_instrument where agg_measures_instrument.sub_depth in (1) union all select agg_measures_underlying."lhu", agg_measures_underlying."underlying_ref", agg_measures_underlying."position_ref", agg_measures_underlying.sub_depth from agg_measures_underlying where agg_measures_underlying.sub_depth in (1, 2, 3) union all select agg_measures_underlying_pair."lhu", NULL, agg_measures_underlying_pair."position_ref", agg_measures_underlying_pair.sub_depth from agg_measures_underlying_pair where agg_measures_underlying_pair.sub_depth in (1))) select s."lhu"::varchar as "lhu", s."underlying_ref"::varchar as "underlying_ref", s."position_ref"::varchar as "position_ref", s.row_depth, case when s.row_depth in (2) then null else agg_measures_position."daily_trading_pnl" end as "daily_trading_pnl", case when s.row_depth in (2, 3) then null else agg_measures_instrument."npv" end as "npv", agg_measures_underlying."delta01" as "delta01", agg_measures_underlying."gamma01" as "gamma01", agg_measures_underlying."vega01" as "vega01", case when s.row_depth in (2, 3) then null else agg_measures_underlying_pair."cross_gamma02" end as "cross_gamma02" from spine s left join agg_measures_position on agg_measures_position."lhu" is not distinct from s."lhu" and agg_measures_position."position_ref" is not distinct from s."position_ref" and agg_measures_position.sub_depth = case s.row_depth when 0 then 0 when 1 then 1 when 2 then 1 when 3 then 2 else -1 end left join agg_measures_instrument on agg_measures_instrument."lhu" is not distinct from s."lhu" and agg_measures_instrument."position_ref" is not distinct from s."position_ref" and agg_measures_instrument.sub_depth = case s.row_depth when 0 then 0 when 1 then 1 when 2 then 1 when 3 then 2 else -1 end left join agg_measures_underlying on agg_measures_underlying."lhu" is not distinct from s."lhu" and agg_measures_underlying."underlying_ref" is not distinct from s."underlying_ref" and agg_measures_underlying."position_ref" is not distinct from s."position_ref" and agg_measures_underlying.sub_depth = case s.row_depth when 0 then 0 when 1 then 1 when 2 then 2 when 3 then 3 else -1 end left join agg_measures_underlying_pair on agg_measures_underlying_pair."lhu" is not distinct from s."lhu" and agg_measures_underlying_pair."position_ref" is not distinct from s."position_ref" and agg_measures_underlying_pair.sub_depth = case s.row_depth when 0 then 0 when 1 then 1 when 2 then 1 when 3 then 2 else -1 end order by s.row_depth asc, s."lhu" asc, s."underlying_ref" asc, s."position_ref" asc
